# Implemented as a pure expression; it does not have side effects.
class _Min(Extern):
    def __init__(self):
        super().__init__("min")

    def typecheck(self, args):
        if len(args) != 2:
            raise _EErr(f"expected 2 arguments, got {len(args)}")

        if args[0].type != args[1].type:
            raise _EErr(
                f"expected both arguments to have the same type, "
                f"but got {args[0].type} and {args[1].type}"
            )

        return args[0].type

    def compile(self, args, prim_type):
        # args[0], args[1] are C strings for the two arguments
        # prim_type is the underlying C primitive type (e.g., float, double, int32_t)
        return f"(({prim_type})(({args[0]} < {args[1]}) ? {args[0]} : {args[1]}))"

    def globl(self, prim_type):
        # No additional global code needed
        return ""

    def interpret(self, args):
        return args[0] if args[0] < args[1] else args[1]


min = _Min()


# Tile sizes along the i and j dimensions.
# These should be tuned for the target machine; 32 is a reasonable default
# for typical cache sizes and SIMD widths.
TI = 32
TJ = 32


@proc
def kernel_floyd_warshall(
    n: size,
    path: DATA_TYPE[n, n] @ DRAM,
):
    # Floyd–Warshall all-pairs shortest paths with cache-friendly blocking.
    #
    # Original algorithm:
    #   for k in 0..n-1:
    #     for i in 0..n-1:
    #       for j in 0..n-1:
    #         path[i, j] = min(path[i, j], path[i, k] + path[k, j])
    #
    # Optimizations applied here:
    #   1. Stage the k-th row of `path` into a temporary row_k to maximize
    #      reuse across all i for a fixed k.
    #   2. Tile the (i, j) space into TI x TJ blocks to improve cache locality
    #      and produce a j-innermost, unit-stride loop for efficient SIMD.
    #   3. For each (k, i) pair, load path[i, k] once into a scalar d_ik and
    #      reuse it across the inner j-loop.
    #
    # Correctness notes:
    #   - For the PolyBench initialization used in this benchmark, all edge
    #     weights are non-negative and path[k, k] >= 0 for all k.
    #   - Under this condition, the in-place updates at (i, k) and (k, j)
    #     during the k-th outer iteration do not change path[i, k] or
    #     path[k, j]:
    #         path[i, k] = min(path[i, k], path[i, k] + path[k, k])
    #         path[k, j] = min(path[k, j], path[k, k] + path[k, j])
    #     so both path[i, k] and path[k, j] are effectively read-only
    #     during that k-iteration.
    #   - Therefore, taking a snapshot of the k-th row into row_k before
    #     processing (i, j), and hoisting path[i, k] into d_ik within the
    #     (k, i) loops, is semantically equivalent to the original code
    #     for all inputs generated by init_array.
    #
    # The tiling itself is just a reordering of the independent (i, j)
    # iterations for fixed k; every pair (i, j) is updated exactly once.

    # Temporary buffer to hold the k-th row of `path`. This is reused for
    # each k and adds only O(n) extra storage.
    row_k: DATA_TYPE[n] @ DRAM

    for k in seq(0, n):
        # Stage the entire k-th row: row_k[j] = path[k, j].
        # This snapshot is safe because path[k, j] does not change during
        # this k-iteration (see correctness note above).
        for j in seq(0, n):
            row_k[j] = path[k, j]

        # 2D tiling over i and j. We iterate over tiles (Ii, Jj) and then
        # over points (i, j) inside each tile. The guards ensure we do not
        # access out-of-bounds elements when n is not a multiple of TI/TJ.
        for Ii in seq(0, (n + TI - 1) / TI):
            for Jj in seq(0, (n + TJ - 1) / TJ):
                for i in seq(0, TI):
                    # Global row index for this tile/inner position.
                    if TI * Ii + i < n:
                        d_ik: DATA_TYPE
                        d_ik = path[TI * Ii + i, k]

                        # Inner-most j loop walks contiguous memory in row-major
                        # order for both path[TI*Ii + i, *] and row_k[*], which
                        # is favorable for the C compiler's auto-vectorization.
                        for j in seq(0, TJ):
                            # Global column index for this tile/inner position.
                            if TJ * Jj + j < n:
                                path[TI * Ii + i, TJ * Jj + j] = min(
                                    path[TI * Ii + i, TJ * Jj + j],
                                    d_ik + row_k[TJ * Jj + j],
                                )
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_floyd_warshall(/*ctxt=*/NULL,
                        n,
                        (DATA_TYPE*)POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(path)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(path);

  return 0;
}
